<?php $this->layout('default'); use Moves\Services\CmsAdmins as A; use Moves\Services\CmsAuth; use Moves\Support\CmsView as V; $roles = array_values(array_filter(A::roles(), static fn ($r) => $r['role_key'] !== 'superadmin')); $matrix = A::matrix(); ?>
<div class="cms-alert cms-alert-info">O Superadministrador tem todas as permissões e não pode ser alterado.</div>
<form class="cms-card" method="post" action="/acao/permissions-save"><?= V::csrf() ?><div class="cms-table-wrap" tabindex="0" role="region" aria-label="Matriz de permissões"><table><thead><tr><th>Permissão</th><?php foreach ($roles as $r): ?><th><?= V::e($r['name']) ?></th><?php endforeach; ?></tr></thead><tbody><?php foreach (CmsAuth::PERMISSIONS as $key => $label): ?><tr><td><?= V::e($label) ?></td><?php foreach ($roles as $r): ?><td><input type="checkbox" aria-label="<?= V::e($label . ' para ' . $r['name']) ?>" name="matrix[<?= (int) $r['id'] ?>][<?= V::e($key) ?>]" value="1"<?= isset($matrix[(int) $r['id']][$key]) ? ' checked' : '' ?>></td><?php endforeach; ?></tr><?php endforeach; ?></tbody></table></div><p><button class="cms-btn-primary">Salvar permissões</button></p></form>
